def transform(grid):
    """Extend every adjacent same-color diagonal pair in both directions to obstacles or edges."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            # Each undirected diagonal adjacency is considered once.
            for dr, dc in ((1, -1), (1, 1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                # Extend both ends of this adjacent pair; preserve all existing non-background cells.
                for sr, sc in ((-dr, -dc), (dr, dc)):
                    rr, cc = (r, c) if (sr, sc) == (-dr, -dc) else (r2, c2)
                    rr += sr
                    cc += sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
